import './App.css';

import minecraftItems from 'minecraft-items';
import items121 from './items121.json';
import { Slot } from './slot';
import React, { Component } from 'react';

const DEFAULT_ICON = 'iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAQAAADZc7J/AAAAF0lEQVRIDWMYBaNgFIyCUTAKRsEoQAMACCAAATXQUGAAAAAASUVORK5CYII=';

// Merge items and ensure uniqueness by name
const allItems = [...minecraftItems.find('')];
const existingNames = new Set(allItems.map(i => i.name.toLowerCase()));

items121.forEach(item => {
  const name = item.displayName;
  if (!existingNames.has(name.toLowerCase())) {
    allItems.push({
      name: name,
      icon: DEFAULT_ICON, // Fallback icon
      id: item.id
    });
  }
});

const findItems = (query) => {
  if (!query) return allItems;
  return allItems.filter(item => 
    item.name.toLowerCase().includes(query.toLowerCase())
  );
}

export class Search extends Component {
  state = {
    items: []
  }
  componentDidMount() {
    this.setState({
      items: findItems('').slice(0,54)
    });
  }
  handleChange = (e) => {
    let search = findItems(e.target.value).slice(0,53);

    let empty = new Array(54-search.length).fill({empty: true})
    let items = [...search, ...empty];
    console.log(items);
    this.setState({
      items,
    });
  }
  render() {
    return(
      <div>
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            marginBottom: '2px'
          }}
        >
          <span>{this.props.title}</span>
          <input
          type="text"
          name="search"
          onChange={this.handleChange}
          />
        </div>
        <div
          id="itemsSearch"
          style={{
            justifyContent: 'center',
          }}
        >
          {this.state.items.map((itm, index) => (
            <div key={itm.id || index} onClick={() => { if (!itm.empty) this.props.selectedFromSearch(itm) }}>
              <Slot
                selectedSlot={this.props.selectedFromSearch}
                key={itm.id || index}
                icon={itm.icon}
                isSearch={true}
              />
          </div>
          ))}
        </div>
      </div>
    )
  }

}
